                reader.onload = (ev) => {
                  const text = (ev.target?.result as string) ?? "";
                  setLocalExamples((prev) => { const next = [...prev]; next[0] = { ...next[0], output: text.slice(0, 2000) }; return next; });
                  setConflicts((prev) => prev.map((c, i) => i === 0 ? null : c));
